$base=['ean'=>'96385074','name'=>'Producto','kind'=>'boxes','pack_size'=>12,'inner_pack_size'=>0,'branch_name'=>'Local A','public_name'=>'Nombre público','owner_name'=>'Nombre privado'];
$lots=[ $base+['units'=>24,'expires'=>'2026-12-01','code'=>'00000001'], $base+['units'=>36,'expires'=>'2026-12-15','code'=>'00000002'], $base+['units'=>12,'expires'=>'2026-12-01','code'=>'00000002'] ];$data=supervisor_export_groups($lots);$g=$data['96385074'];export_ok($g['stock']===72&&$g['uxb']===12,'one product, real total, numeric UXB');export_ok($g['expires']==="01/12/2026: 36 unidades\n15/12/2026: 36 unidades",'all dates with accurate subtotals');export_ok($g['pallets']==="00000001\n00000002",'only unique pallet numbers, preserving leading zeros across dates');export_ok($g['branches']==='Local A','only unique branch names');export_ok($g['members']==='Nombre público'&&!str_contains(json_encode($g),'Nombre privado'),'only unique public names');

$nested=$lots;$nested[0]['pack_size']=180;$nested[0]['inner_pack_size']=30;export_ok(supervisor_export_groups([$nested[0]])['96385074']['uxb']===180,'UXB means total units in outer box, including inner packs');$loose=$lots;$loose[0]['kind']='units';$loose[0]['pack_size']=1;export_ok(supervisor_export_groups([$loose[0]])['96385074']['uxb']==='','unknown UXB stays empty');
$mixed=$lots;$mixed[1]['pack_size']=18;$mixed[2]['kind']='units';$mixed[2]['pack_size']=1;$m=supervisor_export_groups($mixed)['96385074'];export_ok($m['uxb']==='12 / 18','mixed UXB only lists known sizes without stock quantities');$unknown=$lots;$unknown[0]['expires']='';$u=supervisor_export_groups($unknown)['96385074'];export_ok(str_contains($u['expires'],'Sin vencimiento: 24 unidades'),'undated stock accounted');
