$source=supervisor_write_xlsx([['Pedido'],[],[],['EAN','Original'],['96385074','Mantener'],['96385074','Repetido'],['4006381333931','Sin stock'],[]]);$parsed=supervisor_parse_xlsx($source,'A');$out=supervisor_compare_xlsx($source,$parsed['sheet_path'],$parsed['ean_rows'],['96385074'=>72],4,$cols,$data);
supervisor_archive($out,function($zip)use($g){[, $r]=supervisor_cells($zip,'xl/worksheets/sheet1.xml');export_ok($r[4]['C']['value']==='UXB'&&$r[5]['C']['value']==='12'&&$r[5]['D']['value']===$g['expires']&&$r[6]['D']['value']===$g['expires'],'compare appends selected fields on original rows, including duplicates');export_ok($r[5]['B']['value']==='Mantener'&&$r[7]['D']['value']===''&&!isset($r[8]['C']),'original, no-stock and empty rows preserved');export_ok(isset($zip['xl/styles.xml']),'new multiline cells have styles');export_ok($r[4]['E']['value']==='Palets'&&$r[5]['E']['value']==="00000001\n00000002",'XLSX keeps plain numbers and leading zeros');});
try{supervisor_text_cell(new DOMDocument(),'A1',str_repeat('x',32768));throw new Exception('Expected cell limit');}catch(CatalogException $e){export_ok($e->status===422,'no silent cell truncation');}
try{$budget=0;supervisor_export_budget($budget,str_repeat('x',6000001));throw new Exception('Expected export limit');}catch(CatalogException $e){export_ok($e->status===422,'no unbounded repeated detail export');}
