$knownAndLoose=[$base+['units'=>224,'expires'=>'2027-01-01','code'=>'00000001'],array_replace($base,['kind'=>'units','pack_size'=>1,'units'=>1,'expires'=>'2027-01-01','code'=>'00000002'])];$clean=supervisor_export_groups($knownAndLoose)['96385074'];export_ok($clean['uxb']===12&&$clean['expires']==='01/01/2027','known size kept with loose units; single date has no amounts');$knownAndLoose[0]['pack_size']=14;$clean=supervisor_export_groups($knownAndLoose)['96385074'];export_ok($clean['uxb']===14&&$clean['stock']===225,'requested example: UXB14 despite one unit without packing');

export_ok(supervisor_export_boxes([12=>264],1)==='22 + 1 unidad','compact requested box and loose unit summary');export_ok(array_keys(supervisor_export_columns(['columns'=>'expires,boxes,stock']))===['stock','boxes','expires'],'boxes immediately follow units regardless of selection order');$fit=supervisor_export_widths(['stock'=>'Unidades','boxes'=>'Cajas','expires'=>'Vencimientos'],[['stock'=>265,'boxes'=>'22 + 1 unidad','expires'=>'01/01/2027']]);export_ok($fit['stock']===10&&$fit['boxes']===15&&$fit['expires']===14,'compact content-derived widths');

$plain=supervisor_export_columns(['columns'=>'pallets,branches,members']);export_ok(array_values($plain)===['Palets','Sucursales','Integrantes'],'simple headings');$names=$lots;$names[]=array_replace($base,['units'=>1,'expires'=>'2027-01-01','code'=>'05121614','branch_name'=>'Local B','public_name'=>'Otra persona']);$named=supervisor_export_groups($names)['96385074'];export_ok($named['pallets']==="00000001\n00000002\n05121614"&&$named['branches']==="Local A\nLocal B"&&$named['members']==="Nombre público\nOtra persona",'multiple unique values, one per line, no amounts');

$descriptions=$lots;$descriptions[1]['name']='Otra referencia del mismo EAN';$description=supervisor_export_groups($descriptions)['96385074'];export_ok($description['name']==='Producto'&&$description['stock']===72&&$description['expires']===$g['expires'],'one description per EAN despite different names and dates, full totals retained');$descriptions[0]['name']='';export_ok(supervisor_export_groups($descriptions)['96385074']['name']==='Otra referencia del mismo EAN','first available nonempty description');$nameColumns=supervisor_export_columns(['columns'=>'name,expires']);$nameExport=supervisor_compare_xlsx($source,$parsed['sheet_path'],$parsed['ean_rows'],['96385074'=>72],4,$nameColumns,['96385074'=>$description]);supervisor_archive($nameExport,function($zip){[, $rows]=supervisor_cells($zip,'xl/worksheets/sheet1.xml');export_ok($rows[5]['C']['value']==='Producto'&&!str_contains($rows[5]['C']['value'],"\n"),'Excel writes description once per product');});
